def clean(text):
    return " ".join(text.lower().split())

def pipeline(raw):
    text = clean(raw)
    tokens = text.split()
    return {"text": text, "tokens": tokens, "count": len(tokens)}

print(pipeline("  Python   makes AI work  "))
